-- El juego de caracteres se fija SIEMPRE: el cliente mysql lo toma del entorno y en un
-- contenedor sin locale eso es latin1, que convierte cada tilde en mojibake sin dar error.
SET NAMES utf8mb4;

-- ================================================================================================
-- Sierra de El Carche · Fase 3 (N3): puntos de interés.
--
-- GENERADO por Tools/catalogo-nacional/build-poi-sql.js desde el bloque `pointsOfInterest` de
-- Frontend/Data/parks/murcia/sierra-de-el-carche/park.json. No editar a mano: regenerar con
--   node Tools/catalogo-nacional/build-poi-sql.js --park sierra-de-el-carche
--
-- Hace falta porque Frontend/Js/data.js da PRIORIDAD a la API sobre el park.json empaquetado: en un
-- despliegue con backend, sin este SQL el espacio se seguiría sirviendo con 0 puntos de interés.
--
-- ANTES DE APLICAR, comprobar que el espacio tiene fila en `parks`. Si no la tiene, el
-- INSERT ... SELECT de abajo no encuentra nada y **carga cero filas sin dar ningún error** (le pasó
-- a Sierra Espuña el 2026-08-08):
--   SELECT id, slug, name FROM parks WHERE slug = 'sierra-de-el-carche';
--
-- Idempotente: ON DUPLICATE KEY UPDATE sobre la clave única (park_id, slug). Aplicar con:
--   docker exec -i naturdex-db-1 sh -c 'MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql --default-character-set=utf8mb4 naturadex' < Database/n3-pois-sierra-de-el-carche.sql
-- ================================================================================================

-- 10 punto(s) de interés.
INSERT INTO points_of_interest (park_id, slug, name, type, description, latitude, longitude, image_url, source, is_approx, orden)
SELECT p.id, poi.slug, poi.name, poi.type, poi.description, poi.latitude, poi.longitude, poi.image_url, poi.source, poi.is_approx, poi.orden
FROM parks p
JOIN (
    SELECT 'pozo-de-la-nieve' slug, 'Pozo de la Nieve' name, 'Cultural' type, 'Pozo de nieve de 1683, en la umbría de La Madama. Se llenaba en invierno con la nieve pisada de la cumbre para venderla en verano, y es la edificación histórica más relevante del parque y la que más visitas recibe. Fue restaurado en 2017. Sube hasta él una senda propia, y de ella han ido saliendo sendas secundarias que el plan de gestión señala como una de las pocas afecciones por uso público que tiene el espacio.' description, 38.430215 latitude, -1.162779 longitude, NULL image_url, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103, de 6 de mayo de 2025, anuncio 2033), volumen III (Plan Rector de Uso y Gestión del Parque Regional «Sierra del Carche»), §2.3.5 «Patrimonio cultural» (el pozo, su fecha y la restauración de 2017) y §2.3.4.6 «Uso público y recreativo» (las sendas secundarias). Coordenada de la edificación mapeada en OpenStreetMap (way/382889798).' source, FALSE is_approx, 0 orden
    UNION ALL
    SELECT 'pico-de-la-madama', 'Pico de La Madama', 'Paisajístico', 'Techo del parque, a 1.372 m. En la cumbre hay un refugio municipal de Jumilla —una cabaña de madera sobre base de piedra, sin instalaciones, donde caben diez personas— que los visitantes usan sobre todo como mirador, además de un observatorio meteorológico y varias antenas. A cincuenta metros del refugio hay una pequeña rampa de despegue de parapente y ala delta. En su umbría se conservan los pinares relícticos de pino salgareño que son el hábitat prioritario más escaso del espacio.', 38.427701, -1.164017, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103, de 6 de mayo de 2025, anuncio 2033), volumen III, §2.1.4 «Relieve y geomorfología» (la cota) y §2.3.4.6 «Uso público y recreativo» (el refugio, el observatorio, las antenas y la rampa de parapente). Coordenada del vértice mapeado en OpenStreetMap (node/3860985324, cota 1.371 m). El refugio no se da de alta aparte: está en la misma cumbre y lo impediría la regla de proximidad del §4.3.7.', FALSE, 1
    UNION ALL
    SELECT 'albergue-de-la-pena', 'Albergue de La Peña', 'Acceso', 'Albergue del ayuntamiento de Jumilla en el Collado del Revolcador, a unos 1.000 m, en la zona norte del parque. Tiene capacidad para treinta personas, es accesible para personas con movilidad reducida y su uso está destinado a asociaciones. Es, con la cumbre, la zona que más visitantes concentra. El plan de gestión desaconseja el uso recreativo de su explanada en época de riesgo de incendio y advierte de que en las proximidades nidifican el halcón peregrino y el búho real.', 38.444601, -1.168606, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103, de 6 de mayo de 2025, anuncio 2033), volumen III, §2.3.4.6 «Uso público y recreativo», que lo describe con su capacidad y su accesibilidad, y §2.3.4.6 «Efectos ambientales» para las cautelas. Coordenada del edificio mapeado en OpenStreetMap (way/382480423, «Albergue del Carche»); el Collado del Revolcador que el plan cita como su paraje está a 110 m (node/12690472492, cota 995 m).', FALSE, 2
    UNION ALL
    SELECT 'refugio-los-lomazos', 'Refugio de Los Lomazos', 'Acceso', 'Refugio del sur del parque, a unos 640 m de altitud. Es una construcción abierta pero techada, con dos barbacoas instaladas y sin ningún otro servicio. Queda en la vertiente meridional, la más abrupta de la sierra, donde el relieve lo marcan los escarpes y las crestas de las calizas del Eoceno medio.', 38.417758, -1.213937, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103, de 6 de mayo de 2025, anuncio 2033), volumen III, §2.3.4.6 «Uso público y recreativo» (el refugio y sus barbacoas) y §2.1.4 (el relieve de la vertiente sur). Coordenada aproximada: es el topónimo «Los Lomazos» del Instituto Geográfico Nacional que representa el paraje (OpenStreetMap node/1243050534), no un punto medido sobre la construcción, que no está mapeada.', TRUE, 3
    UNION ALL
    SELECT 'sucesion-cretacica-del-carche', 'Sucesión cretácica y paleógena del Carche', 'Geológico', 'La sierra entera es un lugar de interés geológico de valor científico muy alto: en sus terraplenes se lee, sin interrupciones, la serie de sedimentos marinos que va del Barremiense superior al Cenomaniense inferior y, tras una laguna, del Santoniense superior al Mioceno. Sobre ella se estableció la biozonación de referencia del Prebético para todo el Cretácico y el Paleógeno, y es uno de los pocos sitios del Prebético donde el Paleoceno está bien representado. En las calizas se reconocen bancos enteros de rudistas, ostreidos y corales.', 38.429797, -1.159266, NULL, 'Inventario Español de Lugares de Interés Geológico (IELIG, IGME), LIG PT092 «Sucesión cretácica y paleógena de la Sierra del Carche», de interés principal estratigráfico y valor científico muy alto; Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103, de 6 de mayo de 2025, anuncio 2033), volumen III, §2.1.2 «Geología», que lo cita como punto de interés geológico del inventario nacional. Coordenada aproximada: el LIG es un polígono de 2.062 ha que cae íntegro dentro del parque y ocupa el 35 % de su superficie, así que se usa el centro de su pieza mayor y no un afloramiento concreto. La propia ficha del IELIG dice que la serie se reconoce a lo largo de los terraplenes de las pistas forestales.', TRUE, 4
    UNION ALL
    SELECT 'diapiro-de-la-rosa', 'Diapiro de La Rosa', 'Geológico', 'Domo salino que forma el extremo occidental del parque y el diapiro de mayor extensión de la Región de Murcia. Los materiales que lo levantan —yesos, arcillas abigarradas y dolomías del Triásico— son los más antiguos que afloran en la comarca, y su plasticidad explica la forma abombada del relieve y sus colores rojizos, ocres y blanco-grisáceos. La erosión fluvial lo ha ido incidiendo hasta dejar un paisaje acarcavado, más desarrollado en la mitad suroeste. A diferencia de los demás diapiros triásicos del Prebético oriental, que se alinean de nordeste a suroeste, este se inyectó de noroeste a sudeste a través de la falla de Ontur-Jumilla.', 38.431588, -1.223947, NULL, 'Inventario Español de Lugares de Interés Geológico (IELIG, IGME), LIG PT097 «Diapiro de La Rosa», de interés principal tectónico y valor científico alto, con intereses secundarios minero-metalogenético, geomorfológico, petrológico y mineralógico; Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103, de 6 de mayo de 2025, anuncio 2033), volumen III, §2.1.2 «Geología» y §2.1.4 «Relieve y geomorfología». Coordenada aproximada: el LIG es un polígono de 852 ha, del que 850 caen dentro del parque, y se usa el centro de su pieza mayor. La sal del diapiro se explota en las salinas del extremo oeste, que son terreno industrial privado y quedan fuera de lo visitable.', TRUE, 5
    UNION ALL
    SELECT 'alto-del-revolcador', 'Alto del Revolcador', 'Paisajístico', 'Cima de 1.064 m en el norte del parque, una de las tres que el plan de gestión nombra por superar los mil metros además de La Madama. Domina la vertiente septentrional, donde la red de drenaje está muy desarrollada y ha excavado barrancos profundos entre laderas de calizas y areniscas del Cretácico inferior.', 38.445896, -1.169041, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103, de 6 de mayo de 2025, anuncio 2033), volumen III, §2.1.4 «Relieve y geomorfología», que la cita por su nombre entre las cimas que superan los mil metros y describe la vertiente norte. Coordenada del vértice mapeado en OpenStreetMap (node/12690472500, cota 1.064 m).', FALSE, 6
    UNION ALL
    SELECT 'morra-del-buho', 'Morra del Búho', 'Paisajístico', 'Cima de 1.275 m en el centro del parque, la segunda del espacio tras La Madama y otra de las que el plan de gestión nombra por superar los mil metros. Los mayores relieves de este núcleo central coinciden con un potente paquete de dolomías masivas del Cretácico superior, que es lo que forma los escarpes más abruptos de la sierra; en algunas de sus laderas se han descrito derrubios y canchales fósiles con fenómenos de periglaciarismo.', 38.436527, -1.144335, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103, de 6 de mayo de 2025, anuncio 2033), volumen III, §2.1.4 «Relieve y geomorfología», que la cita por su nombre y describe las dolomías cenomanienses y los canchales periglaciares del núcleo central. Coordenada del vértice mapeado en OpenStreetMap (node/12690472502, cota 1.275 m).', FALSE, 7
    UNION ALL
    SELECT 'sierra-de-las-pansas', 'Sierra de las Pansas', 'Paisajístico', 'Sector oriental del parque, con un relieve gemelo al de la Sierra del Carche y el Cerro de Pansas por encima de los mil metros. Es la parte del espacio más alejada de los accesos y la que conserva la mancha forestal más continua.', 38.457679, -1.115805, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103, de 6 de mayo de 2025, anuncio 2033), volumen III, §2.1.4 «Relieve y geomorfología», que la sitúa en la parte más oriental del parque «con un relieve similar a la Sierra del Carche» y cita el Cerro de Pansas entre las cimas de más de mil metros. Coordenada aproximada: es el topónimo «Las Pansas» que representa el sector (OpenStreetMap node/12688629615), no una cima medida. El nodo cae 4 m FUERA del límite oficial, dentro del margen de ~50 m que el §4.3.3 admite para no descartar lo que roza el borde; el sector que representa sí está dentro.', TRUE, 8
    UNION ALL
    SELECT 'pozo-del-mosquito', 'Pozo del Mosquito', 'Cultural', 'Pozo en ruinas en la vertiente norte del macizo central, junto al puntal que lleva su nombre. Los pozos y aljibes repartidos por la sierra recogían el agua de escorrentía en un terreno donde no hay cauces permanentes: la Sierra del Carche es divisoria de aguas y solo tiene barrancos y ramblas de recorrido corto y régimen torrencial.', 38.436262, -1.165426, NULL, 'OpenStreetMap (way/382891317, building=yes historic=ruins), que es quien lo nombra y lo sitúa. El Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103, de 6 de mayo de 2025, anuncio 2033), volumen III, §2.3.5 menciona los aljibes del parque como elementos de interés pero no los enumera uno a uno, así que la identificación de este en concreto no está contrastada con la norma; el §2.1.5.1 sí es la fuente de lo que se dice de la red de drenaje. Pendiente de contrastar sobre el terreno.', FALSE, 9
) poi
WHERE p.slug = 'sierra-de-el-carche'
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    type = VALUES(type),
    description = VALUES(description),
    latitude = VALUES(latitude),
    longitude = VALUES(longitude),
    image_url = VALUES(image_url),
    source = VALUES(source),
    is_approx = VALUES(is_approx),
    orden = VALUES(orden);

-- Comprobación posterior: debe devolver 10.
SELECT COUNT(*) AS pois_cargados FROM points_of_interest poi
JOIN parks p ON p.id = poi.park_id WHERE p.slug = 'sierra-de-el-carche';
